    encoded_message = ''
    for char in message:
        if char.isalpha():
            if char in vowels:
                if char.islower():
                    encoded_char = chr((ord(char) - ord('a') + 2) % 26 + ord('a'))
                else:
                    encoded_char = chr((ord(char) - ord('A') + 2) % 26 + ord('A'))
