def simplify(x, n):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def lcm(a, b):
        return a * b // gcd(a, b)

    x_num, x_den = map(int, x.split('/'))
    n_num, n_den = map(int, n.split('/'))

    product_num = x_num * n_num
    product_den = x_den * n_den

    g = gcd(product_num, product_den)
    simplified_num = product_num // g
    simplified_den = product_den // g

    return simplified_den == 1

